1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const basePremiumOf = (item: Item): number =>
25	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
26	
27	const sumBasePremiums = (items: Item[]): number =>
28	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
29	
30	const BLOCK_SIZE = 3;
31	const BLOCK_BASE_PREMIUM = 60;
32	
33	const formsComponentBlock = (items: Item[]): boolean =>
34	  items.length === BLOCK_SIZE &&
35	  items.every((item) => item.type === items[0].type);
36	
37	export const quote = (customer: Customer, items: Item[]): number => {
38	  const policyBasePremium = formsComponentBlock(items)
39	    ? BLOCK_BASE_PREMIUM
40	    : sumBasePremiums(items);
41	
42	  return policyBasePremium + PROCESSING_FEE;
43	};
44	
45	export const claim = (): number => {
46	  return undefined as unknown as number;
47	};
